"""Scheduler module for job scheduling."""

import logging
import time
from typing import Any, Callable, Dict, Optional

from .models import Job

logger = logging.getLogger(__name__)

_jobs: Dict[str, Job] = {}


def register_job(name: str, func: Callable, interval: float = 60.0, enabled: bool = True) -> None:
    """Register a job to run periodically."""
    if name in _jobs:
        logger.warning(f"Job {name} already registered, replacing")
    _jobs[name] = Job(func, interval, enabled)
    logger.info(f"Registered job: {name} (interval={interval}s)")


def run_pending() -> Dict[str, Any]:
    """Execute all jobs that are due."""
    results: Dict[str, Any] = {}
    for name, job in _jobs.items():
        if job.is_due():
            logger.info(f"Running job: {name}")
            result = job.execute()
            results[name] = result
    return results


def run_loop(check_interval: float = 1.0, max_iterations: Optional[int] = None) -> None:
    """Main scheduler loop. Runs pending jobs on each tick."""
    iteration = 0
    while max_iterations is None or iteration < max_iterations:
        results = run_pending()
        if results:
            logger.debug(f"Tick {iteration}: ran {len(results)} job(s)")
        time.sleep(check_interval)
        iteration += 1


def clear_all() -> None:
    """Remove all registered jobs."""
    _jobs.clear()


def disable_job(name: str) -> None:
    """Disable a job without removing it."""
    job = _jobs.get(name)
    if job:
        job.enabled = False


def enable_job(name: str) -> None:
    """Enable a previously disabled job."""
    job = _jobs.get(name)
    if job:
        job.enabled = True
